const TIME_LIMIT: int = 4204;
const TH14_RICE: int = 480;
const TH14_DROPLET: int = 896;
// Single-card mailbox: no reuse or allocation recovery. Fewer than 484 marked
// bullets can be emitted before source timeout (minimum I2 is 29).
const EMIT_SERIAL: int = 16;
const SOURCE_END: int = 18;
const COLORS: int = 32;
xformdef MARK_COLOR(slot: int) {
again:
    @1 set_color(at_effect(global(slot)));
    goto again;
}
sub marked(serial: int) {
    var state: int = 1;
    var pc: int = 0;
    var t: int = 0;
    var logical_speed: fx = $self_speed;
    var logical_angle: angle = $self_angle;
    var turn_speed: fx = logical_speed;
    var turn_angle: angle = logical_angle;
    var ax: fx = 0fx;
    var ay: fx = 0fx;
    var delta: fx = 0fx;
    loop {
        var distance: fx = dist($self_x - $player_x, $self_y - $player_y);
        if (state == 1 && distance < 64fx) {
            state = 2; pc = 5; t = 0;
            stop_fx(0);
            turn_speed = logical_speed; turn_angle = logical_angle;
            set_global(COLORS + serial, 1); // source EX5 type32/color1
        } else {
            if (state == 2 && distance >= 128fx) {
                state = 1; pc = 14; t = 0;
                stop_fx(0);
                turn_speed = logical_speed; turn_angle = logical_angle;
                set_global(COLORS + serial, 3); // source EX14 type32/color3
            }
        }
        // EX6/15 TURN a30,b1,c0/c1,r0,s0: decelerate with saved
        // logical speed, then restore target zero and resolve segment angle.
        if (pc == 5 || pc == 14) {
            if (t < 30) {
                var v: fx = turn_speed - turn_speed * t / 30;
                set_vel(0, v * cos(turn_angle), v * sin(turn_angle));
                t = t + 1;
            } else {
                logical_speed = 0fx;
                logical_angle = turn_angle;
                if (pc == 14) { logical_angle = aim_player(); }
                set_angle(0, logical_angle);
                set_speed(0, 0fx);
                if (pc == 5) { pc = 7; } else { pc = 16; }
                t = 0;
            }
        }
        // EX7/16 WAIT60; it does not suspend the distance callback.
        if (pc == 7 || pc == 16) {
            if (t == 60) {
                if (pc == 7) {
                    pc = 8;
                    // Prepared TH14 rule: s>=990 resolves player angle + m; m=0.
                    var q: angle = aim_player();
                    ax = 0.02fx * cos(q); ay = 0.02fx * sin(q);
                } else {
                    pc = 17;
                    var exit_q: angle = aim_player();
                    delta = (2fx - logical_speed) / 120;
                    ax = delta * cos(exit_q); ay = delta * sin(exit_q);
                }
                t = 0;
            } else { t = t + 1; }
        }
        // EX8 ACCEL2, EX9 goto8: re-enter every two ticks, preserving
        // current velocity, sampling the direction anew at each entry.
        if (pc == 8) {
            if (t == 2) {
                var repeat_q: angle = aim_player();
                ax = 0.02fx * cos(repeat_q); ay = 0.02fx * sin(repeat_q); t = 0;
            }
            var vx: fx = $self_vx + ax;
            var vy: fx = $self_vy + ay;
            set_vel(0, vx, vy);
            logical_speed = dist(vx, vy); logical_angle = $self_angle;
            t = t + 1;
        }
        // EX17 VELTIME120: fixed direction/linear scalar ramp, not homing.
        if (pc == 17) {
            if (t < 120) {
                set_vel(0, $self_vx + ax, $self_vy + ay);
                logical_speed = logical_speed + delta;
                logical_angle = $self_angle;
                t = t + 1;
            } else { pc = 18; }
        }
        wait(1);
    }
}
// All four start next frame; the next source burst is at least 29 frames
// later, so EMIT_SERIAL-4 is still this wave's first ordinal. No task-order
// assumption, index reuse, queue or allocation protocol is involved.
async sub marked0() { marked(global(EMIT_SERIAL) - 4); }
async sub marked1() { marked(global(EMIT_SERIAL) - 3); }
async sub marked2() { marked(global(EMIT_SERIAL) - 2); }
async sub marked3() { marked(global(EMIT_SERIAL) - 1); }
sub emit_normal(base: angle) {
    // mode10 N4/M48: identical-speed four-way rings permit sh_fire.
    // Odd q reverses ring enumeration but has the same static point set;
    // ordinary bullets have no per-bullet RNG or task consuming that order.
    sh_reset(0); sh_sprite(0, TH14_RICE, 2);
    sh_ring(0, 1); sh_count(0, 4, 1); sh_speed(0, 1fx, 0fx);
    sh_dist(0, 28fx); // etDist32 minus ANIM backward displacement4.
    for q in 0..48 {
        var h: int = (q / 2) * 315 + 157;
        if (q % 2 != 0) { h = -h; }
        sh_angle(0, base + (h as angle), 0deg);
        sh_fire(0);
    }
}
sub emit_marked(base: angle) {
    for i in 0..4 {
        var serial: int = global(EMIT_SERIAL);
        var a: angle = base + ((i * 16384) as angle);
        set_global(COLORS + serial, 3);
        set_global(EMIT_SERIAL, serial + 1);
        var x: fx = $self_x + 28fx * cos(a);
        var y: fx = $self_y + 28fx * sin(a);
        if (i == 0) { _ = fire(TH14_DROPLET, 3, x, y, 1fx, a, MARK_COLOR(COLORS + serial), marked0); }
        if (i == 1) { _ = fire(TH14_DROPLET, 3, x, y, 1fx, a, MARK_COLOR(COLORS + serial), marked1); }
        if (i == 2) { _ = fire(TH14_DROPLET, 3, x, y, 1fx, a, MARK_COLOR(COLORS + serial), marked2); }
        if (i == 3) { _ = fire(TH14_DROPLET, 3, x, y, 1fx, a, MARK_COLOR(COLORS + serial), marked3); }
    }
}
async sub attack() {
    var a: angle = -45deg;
    var rank: int = global(GVAR_RANK);
    var step: angle = 20deg;
    var pattern_index: int = 0;
    if (rank == 0) { step = 30deg; }
    if (rank == 3) { step = 18deg; }
    while ($frame < global(SOURCE_END)) {
        // One RANDF2 sample per ordinary wave, shared over all its bullets.
        var jitter: angle = (rand(365) - 182) as angle;
        emit_normal(a + jitter);
        a = a - 45deg;
        emit_marked(a);
        if (pattern_index == 0 || pattern_index == 3) { a = a - step; }
        else { a = a + step; }
        pattern_index = (pattern_index + 1) % 4;
        wait(self_int(0));
    }
}
async sub boss() {
    var rank: int = global(GVAR_RANK);
    var interval: int = 160;
    set_invuln(65535);
    set_hitbox(24fx); set_hurtbox(24fx);
    set_player_hitbox(2.5fx); // Boss5 funcCall4 restores base radius.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(180); // wrapper reset is distinct from Card5 timerReset.
    set_global(SOURCE_END, $frame + 3600);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);
    if (rank == 2) { interval = 140; }
    if (rank == 3) { interval = 123; }
    set_self_int(0, interval);
    spawn attack();
    wait(90);
    while ($frame < global(SOURCE_END)) {
        if (interval >= 30) {
            if (rank == 0) { interval = interval - 1; }
            else { interval = interval - 2; }
            set_self_int(0, interval);
        }
        var remaining: int = global(SOURCE_END) - $frame;
        if (remaining < 60) { wait(remaining); break; }
        wait(60);
    }
    // Callback clear/next-attack etClear is represented only at source timeout.
    clear_bullets_at(0fx, 0fx, 640fx, 0);
    set_player_hitbox(2.5fx);
}
async sub pattern() {
    set_global(EMIT_SERIAL, 0);
    wait(120);
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, boss);
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
